#!/usr/bin/env python3
"""
gen_key.py — generate a PBKDF2 salt + a build-time secret.

Outputs:
  - android/app/src/main/java/com/optobot/native/OptoBuildSecret.kt
  - android/app/src/main/assets/opto_key.hint  (just the base64 salt)

The .kt file is gitignored — never check it in. The salt is non-secret
on its own (it just slows brute-force PBKDF2).
"""

import argparse
import base64
import os
import secrets

KOTLIN_TEMPLATE = """package com.optobot.native

/** AUTO-GENERATED by scripts/gen_key.py. DO NOT COMMIT. */
object OptoBuildSecret {{
    val BUILD_SECRET: CharArray = "{secret}".toCharArray()
}}
"""

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out-kt", default="android/app/src/main/java/com/optobot/native/OptoBuildSecret.kt")
    ap.add_argument("--out-hint", default="android/app/src/main/assets/opto_key.hint")
    ap.add_argument("--force", action="store_true")
    args = ap.parse_args()

    if os.path.exists(args.out_kt) and not args.force:
        print(f"[optobot] {args.out_kt} already exists. Use --force to overwrite.")
        return

    salt = secrets.token_bytes(32)
    secret = secrets.token_urlsafe(48)

    os.makedirs(os.path.dirname(args.out_kt), exist_ok=True)
    with open(args.out_kt, "w") as f:
        f.write(KOTLIN_TEMPLATE.format(secret=secret))

    os.makedirs(os.path.dirname(args.out_hint), exist_ok=True)
    with open(args.out_hint, "wb") as f:
        f.write(base64.b64encode(salt))

    print(f"[optobot] wrote {args.out_kt}")
    print(f"[optobot] wrote {args.out_hint}")
    print(f"[optobot] salt  = {base64.b64encode(salt).decode()}")
    print(f"[optobot] secret length = {len(secret)} chars")

if __name__ == "__main__":
    main()
